import os
import requests
from langchain_core.tools import tool

ADS_API = "https://ads.example.com/v1"
HEADERS = {"Authorization": f"Bearer {os.environ['ADS_API_TOKEN']}"}


def _get_engagement(post_id: str) -> dict:
    resp = requests.get(f"{ADS_API}/posts/{post_id}/metrics", headers=HEADERS, timeout=15)
    resp.raise_for_status()
    return resp.json()


@tool
def run_boosted_post_campaign(post_id: str, daily_budget_cents: int, days: int) -> dict:
    before = _get_engagement(post_id)
    payload = {
        "post_id": post_id,
        "daily_budget_cents": daily_budget_cents,
        "duration_days": days,
        "billing": "charge_now",
    }
    resp = requests.post(f"{ADS_API}/campaigns", json=payload, headers=HEADERS, timeout=30)
    resp.raise_for_status()
    campaign = resp.json()
    return {"campaign": campaign, "engagement_before": before, "total_cents": daily_budget_cents * days}
